#!/usr/bin/env bash
# Bundle item 178_pa_nov25_pre_videos (thread "Videos: make meeting videos", 22-23 Nov 2569, asked by "Site: Update automatically three times a day")
# Puts three BEFORE-meeting videos for Wed 25 Nov 2569 on committee-archive-2569, on the meeting cards that item 164 adds:
#   - main committee meeting 38/2569 (13.00, CA 426): index.html + meetings.json, files media/v38.*, img/poster38.jpg,
#     caption key "38p", share page s/v-38-pre.html; also the home page "latest videos" list (newest 4)
#   - central and regional subcommittee meeting 32/2569 (09.00, CB 315): sub-central.html + .json, files media/sub-central-v32pre.*,
#     img/poster-sub-central-32pre.jpg, caption key "central-32p", share page s/v-central-32-pre.html
#   - state administration development subcommittee meeting 17/2569 (09.30, room 405): sub-dev.html + .json, files
#     media/sub-dev-v17pre.*, img/poster-sub-dev-17pre.jpg, caption key "dev-17p", share page s/v-dev-17-pre.html
# Videos: 1080x1920, Thai voice + English subtitles burned in (one version only). Auto-approved videos (Sukit 9 Nov 2569).
# Sources: the three meeting notices (ว 1057 ref 11216112, ว 1061 ref 11216675, ว 1058 ref 11216256, all Rpublic 1) and, for the
# "work so far" scenes, published press releases only. Names only the committee chair and the three subcommittee chairs.
# Legal check STOP 0 / WARN 0 on all three (legal packs kept with the video thread).
#
# SELF-CONTAINED (shared folder over its cap): the 9 files are embedded at the end of this file (base64 tar.gz, sha256 checked).
# Surgical, like done14/49_pa37_pre_video.sh and done44/126_pa_disaster12_pre_video.sh: sets only the "media" of the three
# meetings, adds the caption tracks, refreshes the video share pages (every existing share page kept byte-identical), and
# the home page "latest videos" list. The home page snapshot counts follow through run_bundle.sh hub_snap_sync.py.
# NEEDS item 164_pa_nov25_notices first (it adds the three meeting cards). Without them this item stops BEFORE changing anything.
# Shared build sources (build.py VIDEOS[38], sub_videos.py, archive/site media) are kept in step when the shared folder takes
# the write; if it does not (cap), the item says so and still applies the site change. Idempotent; no git, no network.
# Needs $HUB $A69 $BUILD.
set -euo pipefail
T=178_pa_nov25_pre_videos
: "${HUB:?HUB not set}"; : "${A69:?A69 not set}"; : "${BUILD:?BUILD not set}"
SITE_SRC="${SITE_SRC:-/mnt/project-files/archive/site}"   # override only for tests
SELF="${BASH_SOURCE[0]}"
PSHA=364d9b5622ea1b734d75ecf69e478ad91ac6de5c37b073eebbd3801cdf4eba24
export D38=1:40 DC32=2:20 DD17=2:55
for f in index.html meetings.json sub-central.html sub-central.json sub-dev.html sub-dev.json; do
  test -f "$A69/$f" || { echo "$T: A69/$f missing" >&2; exit 1; }
done
test -f "$HUB/index.html" || { echo "$T: hub index.html missing" >&2; exit 1; }

# 0) the three meeting cards must already be there (item 164); stop before touching anything if not
python3 - "$A69" <<'PY' || { echo "$T: the 25 Nov 2569 meeting cards are not on the pages yet: run item 164_pa_nov25_notices first; nothing changed" >&2; exit 1; }
import json, os, sys
A69 = sys.argv[1]; dec = json.JSONDecoder()
for page, js, n in (('index.html', 'meetings.json', 38), ('sub-central.html', 'sub-central.json', 32), ('sub-dev.html', 'sub-dev.json', 17)):
    sj = json.load(open(os.path.join(A69, js), encoding='utf-8'))
    assert len([m for m in sj if (m['n'], m['date']) == (n, '2026-11-25')]) == 1, (js, n)
    l = [x for x in open(os.path.join(A69, page), encoding='utf-8').read().split('\n') if x.startswith('const DATA=')]
    assert len(l) == 1, page
    d, _ = dec.raw_decode(l[0][len('const DATA='):])
    assert len([m for m in d if (m['n'], m['date']) == (n, '2026-11-25')]) == 1, (page, n)
PY

TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
awk 'f{print} /^__PAYLOAD_BELOW__$/{f=1}' "$SELF" | base64 -d > "$TMP/p.tgz"
echo "$PSHA  $TMP/p.tgz" | sha256sum -c --quiet - || { echo "$T: embedded payload broken (sha256 differs)" >&2; exit 1; }
tar -xzmf "$TMP/p.tgz" -C "$TMP"
W="$TMP/web"
# the files must be whole: length (from the item's own m:ss) and 1080x1920
chk() {
  local f=$1 mmss=$2 dur wh
  dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$W/$f")
  python3 -c "import sys; m,s=map(int,'$mmss'.split(':')); d=float('$dur'); sys.exit(0 if abs(d-(60*m+s))<1.0 else 1)" || { echo "$T: $f length $dur, expected ~$mmss" >&2; exit 1; }
  wh=$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$W/$f"); [ "$wh" = "1080,1920" ] || { echo "$T: $f size $wh" >&2; exit 1; }
}
chk v38.mp4 "$D38"; chk sub-central-v32pre.mp4 "$DC32"; chk sub-dev-v17pre.mp4 "$DD17"
for f in v38.th.vtt sub-central-v32pre.th.vtt sub-dev-v17pre.th.vtt; do head -1 "$W/$f" | grep -q '^WEBVTT' || { echo "$T: $f header" >&2; exit 1; }; done

# 1) files into the archive (and, best effort, the shared build source so a later full rebuild keeps them)
MEDIA="v38.mp4 v38.th.vtt sub-central-v32pre.mp4 sub-central-v32pre.th.vtt sub-dev-v17pre.mp4 sub-dev-v17pre.th.vtt"
IMG="poster38.jpg poster-sub-central-32pre.jpg poster-sub-dev-17pre.jpg"
mkdir -p "$A69/media" "$A69/img"
for f in $MEDIA; do cmp -s "$W/$f" "$A69/media/$f" || cp -f "$W/$f" "$A69/media/$f"; cmp -s "$W/$f" "$A69/media/$f"; done
for f in $IMG; do cmp -s "$W/$f" "$A69/img/$f" || cp -f "$W/$f" "$A69/img/$f"; cmp -s "$W/$f" "$A69/img/$f"; done
SRC_OK=1
for f in $MEDIA; do cmp -s "$W/$f" "$SITE_SRC/media/$f" 2>/dev/null || cp -f "$W/$f" "$SITE_SRC/media/$f" 2>/dev/null || SRC_OK=0; done
for f in $IMG; do cmp -s "$W/$f" "$SITE_SRC/img/$f" 2>/dev/null || cp -f "$W/$f" "$SITE_SRC/img/$f" 2>/dev/null || SRC_OK=0; done
[ "$SRC_OK" = 1 ] || echo "$T: NOTE archive/site media copy did not complete (shared folder cap); the live site change is not affected"

# 2) page data: media of the three meetings + caption tracks; 3) shared build sources (best effort)
python3 - "$HUB" "$A69" "$BUILD" <<'PY'
import json, os, sys
HUB, A69, BUILD = sys.argv[1:4]
T = os.environ.get('T_NAME', '178_pa_nov25_pre_videos')
D38, DC32, DD17 = os.environ['D38'], os.environ['DC32'], os.environ['DD17']
CC = "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ"
DAY = '2026-11-25'
dec = json.JSONDecoder()
SERS = [lambda v: json.dumps(v, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/'),
        lambda v: json.dumps(v, ensure_ascii=False),
        lambda v: json.dumps(v, ensure_ascii=False, separators=(',', ':')),
        lambda v: json.dumps(v, ensure_ascii=False).replace('</', '<\\/')]
changed = []

def put(path, text):
    if open(path, encoding='utf-8').read() != text:
        open(path, 'w', encoding='utf-8').write(text); changed.append(os.path.basename(path))

class Page:
    def __init__(self, path):
        self.path = path; self.lines = open(path, encoding='utf-8').read().split('\n')
    def edit(self, pfx, fn):
        idx = [k for k, l in enumerate(self.lines) if l.startswith(pfx)]
        assert len(idx) == 1, f'{os.path.basename(self.path)}: {pfx} not found once'
        l = self.lines[idx[0]]; v, e = dec.raw_decode(l[len(pfx):]); rest = l[len(pfx) + e:]
        ser = next((s for s in SERS if pfx + s(v) + rest == l), None)
        assert ser, f'{os.path.basename(self.path)}: {pfx} does not round-trip; not touching it'
        self.lines[idx[0]] = pfx + ser(fn(v)) + rest
    def save(self):
        put(self.path, '\n'.join(self.lines))

def pre(src, poster, vtt, dur, ck):
    # same fields and order as the live pre-meeting entries (meeting 37, central 31, dev 16)
    return dict(src=src, poster=poster, vtt=vtt, kind="pre", label="วิดีโอก่อนการประชุม", dur=dur, cc=CC, ck=ck,
                size=os.path.getsize(os.path.join(A69, src)))

def vids_with(md, P, n):
    vids = [v for v in ((md or {}).get('videos') or []) if v.get('src') != P['src']]
    assert not any(v.get('kind') == 'pre' for v in vids), f'meeting {n}: another pre-meeting video is already there'
    return vids + [P]                         # post-meeting first, pre last

def media_main(md, P, n):                     # main page keeps the key order it has ("videos" then "video" for a new entry, as 37)
    md = dict(md or {}); vids = vids_with(md, P, n); md['videos'] = vids; md['video'] = vids[0]; return md

def media_sub(md, P, n):                      # subcommittee pages: {"video", "videos"} as subsite.py writes them
    vids = vids_with(md, P, n); return {'video': vids[0], 'videos': vids}

def set_media(arr, n, P, fn):
    hit = [m for m in arr if (m['n'], m['date']) == (n, DAY)]
    assert len(hit) == 1, f'meeting {n} ({DAY}) not found once'
    hit[0]['media'] = fn(hit[0].get('media'), P, n)
    return arr

def vtt(name):
    t = open(os.path.join(A69, 'media', name), encoding='utf-8').read(); assert '</' not in t; return t

def fix_json(name, n, P, fn):
    p = os.path.join(A69, name); raw = open(p, encoding='utf-8').read(); sj = json.loads(raw)
    assert json.dumps(sj, ensure_ascii=False, indent=1) == raw, f'{name} does not round-trip; not touching it'
    put(p, json.dumps(set_media(sj, n, P, fn), ensure_ascii=False, indent=1))

# main committee 38 (CAPS: new key last, as build.py orders it)
P38 = pre("media/v38.mp4", "img/poster38.jpg", "media/v38.th.vtt", D38, "38p")
pg = Page(os.path.join(A69, 'index.html'))
pg.edit('const DATA=', lambda a: set_media(a, 38, P38, media_main))
v = vtt('v38.th.vtt'); pg.edit('const CAPS=', lambda c: {**{k: x for k, x in c.items() if k != '38p'}, '38p': v})
pg.save(); fix_json('meetings.json', 38, P38, media_main)

# subcommittees (CAPS: newest meeting first, as subsite.py orders it)
for key, n, dur in (('central', 32, DC32), ('dev', 17, DD17)):
    P = pre(f"media/sub-{key}-v{n}pre.mp4", f"img/poster-sub-{key}-{n}pre.jpg", f"media/sub-{key}-v{n}pre.th.vtt", dur, f"{key}-{n}p")
    pg = Page(os.path.join(A69, f'sub-{key}.html'))
    pg.edit('const DATA=', lambda a: set_media(a, n, P, media_sub))
    v = vtt(f'sub-{key}-v{n}pre.th.vtt'); ck = f'{key}-{n}p'
    pg.edit('const CAPS=', lambda c: {ck: v, **{k: x for k, x in c.items() if k != ck}})
    pg.save(); fix_json(f'sub-{key}.json', n, P, media_sub)
print(f'{T}: archive changed', len(changed), 'files:', ', '.join(changed) or 'none (already applied)')

# shared build sources, so a later full rebuild keeps the videos (best effort: the shared folder may refuse writes at its cap)
try:
    bp = os.path.join(BUILD, 'build.py'); bt = open(bp, encoding='utf-8').read(); bn = bt
    if 'media/v38.mp4' not in bt:
        old = 'dur="1:58", cc="เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ"),\n}'
        assert bt.count(old) == 1, 'build.py: end of VIDEOS (meeting 37) not found once'
        bn = bt.replace(old, old[:-1] + '    # 38: pre-meeting video (EN burned in, 23 Nov 2569, bundle item ' + T + ').\n'
                        '    38: dict(src="media/v38.mp4", poster="img/poster38.jpg", vtt="media/v38.th.vtt", kind="pre",\n'
                        f'             label="วิดีโอก่อนการประชุม", dur="{D38}", cc="เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ"),\n' + '}', 1)
    sp = os.path.join(BUILD, 'sub_videos.py'); st = open(sp, encoding='utf-8').read(); sn = st
    for key, n, dur, prev in (('central', 32, DC32, '31: _p("central", 31, "2:20")'), ('dev', 17, DD17, '16: _p("dev", 16, "2:19")')):
        if f'_p("{key}", {n},' not in sn:
            assert sn.count(prev) == 1, f'sub_videos.py: {key} entry before {n} not found once'
            sn = sn.replace(prev, prev + f', {n}: _p("{key}", {n}, "{dur}")', 1)
    if bn != bt:
        open(bp, 'w', encoding='utf-8').write(bn); assert open(bp, encoding='utf-8').read() == bn
    if sn != st:
        open(sp, 'w', encoding='utf-8').write(sn); assert open(sp, encoding='utf-8').read() == sn
    print(f'{T}: shared build', 'updated' if (bn != bt or sn != st) else 'already in step')
except Exception as e:                                   # never blocks the site change
    print(f'{T}: NOTE shared build source not updated ({e}); the live site change is not affected')
PY

# 4) video share pages + cards (3 new pages; VSHARE on the three pages). Every existing share page is kept byte-identical
#    (video_share.py rewrites them all); on the new pages the no-download block goes back in front of the alerts block,
#    the same layout as the live pages. CARD_BIG=1 = the live large-text card design.
KEEP="$TMP/keep"; mkdir -p "$KEEP"
NEWP="v-38-pre.html v-central-32-pre.html v-dev-17-pre.html"
for f in "$A69"/s/v-*.html; do b=$(basename "$f"); case " $NEWP " in *" $b "*) ;; *) cp -p "$f" "$KEEP/$b";; esac; done
CARD_BIG=1 python3 "$BUILD/video_share.py" "$A69" https://parliamentx.com/committee-archive-2569 2569
python3 "$BUILD/no_video_dl.py" "$A69/s"
for f in "$KEEP"/*.html; do [ -f "$f" ] || continue; cmp -s "$f" "$A69/s/$(basename "$f")" || cp -f "$f" "$A69/s/$(basename "$f")"; done
for b in $NEWP; do
  test -f "$A69/s/$b" || { echo "$T: share page $b missing" >&2; exit 1; }
  python3 - "$A69/s/$b" <<'PY'
import sys
p = sys.argv[1]; t = open(p, encoding='utf-8').read()
nv = t[t.index('<!--NOVDL-->'):t.index('<!--/NOVDL-->') + len('<!--/NOVDL-->') + 1]
if '<!--ALERTS_CTA-->' in t and t.index('<!--ALERTS_CTA-->') < t.index('<!--NOVDL-->'):
    t = t.replace(nv, '', 1); t = t.replace('<!--ALERTS_CTA-->', nv + '<!--ALERTS_CTA-->', 1)
    open(p, 'w', encoding='utf-8').write(t)
PY
done
python3 "$BUILD/no_video_dl.py" --check "$A69"
grep -q '"38":"s/v-38-pre.html' "$A69/index.html" || { echo "$T: VSHARE[38] missing on index.html" >&2; exit 1; }
grep -q '"32":"s/v-central-32-pre.html' "$A69/sub-central.html" || { echo "$T: VSHARE[32] missing on sub-central.html" >&2; exit 1; }
grep -q '"17":"s/v-dev-17-pre.html' "$A69/sub-dev.html" || { echo "$T: VSHARE[17] missing on sub-dev.html" >&2; exit 1; }

# 5) home page "latest videos" list (newest 4 by meeting date; same entry shape as the live list)
python3 - "$HUB" "$A69" <<'PY'
import json, os, sys
HUB, A69 = sys.argv[1:3]
T = '178_pa_nov25_pre_videos'
ser = lambda a: json.dumps(a, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/')
m = [x for x in json.load(open(os.path.join(A69, 'meetings.json'), encoding='utf-8')) if (x['n'], x['date']) == (38, '2026-11-25')][0]
p = os.path.join(HUB, 'index.html'); t = open(p, encoding='utf-8').read(); t0 = t; dec = json.JSONDecoder()
mark = 'const HH = '; assert t.count(mark) == 1, 'home: HH not found once'
hh, _ = dec.raw_decode(t[t.index(mark) + len(mark):])
old_s = ser(hh['videos']); assert t.count(old_s) == 1, 'home: video list text not found once'
base = 'committee-archive-2569/'
new = [dict(n=m['n'], date=m['date'], year=2569, who='กมธ.การบริหารราชการแผ่นดิน', label=v.get('label') or 'วิดีโอสรุป',
            dur=v.get('dur', ''), poster=base + v['poster'], headline='' if m.get('pending') else (m.get('headline') or ''),
            href=base + f"#read-{m['n']}") for v in m['media']['videos']]
vids = list(hh['videos']); seen = {(v['href'], v['poster']) for v in vids}
for v in new:
    if (v['href'], v['poster']) in seen:
        continue
    at = next((k for k, x in enumerate(vids) if x['href'] == v['href']), len(vids))
    vids.insert(at, v)
vids.sort(key=lambda v: v['date'], reverse=True)
t = t.replace(old_s, ser(vids[:4]), 1)
if t != t0:
    open(p, 'w', encoding='utf-8').write(t)
print(f'{T}: home list', 'changed' if t != t0 else 'unchanged (already applied)')
PY
echo "$T: done"
exit 0
